edits.before:
// Set initial value if input has a value
if (this._isInput && this._element.value) {
  this._parseInputValue()
}

// Populate input/display with preselected dates
this._updateDisplayWithSelectedDates()

edits.after:
// Set initial value if input has a value
if (this._isInput && this._element.value) {
  this._parseInputValue()
}

// Populate display with preselected dates
if (this._displayElement) {
  this._updateDisplayWithSelectedDates()
}

edits.before:
protected _syncSelectedDates(selectedDates: string[]): void {
  const formattedDate = this._formatDateForInput(selectedDates)
  if (this._isInput) {
    this._element.value = formattedDate
  }

  if (this._boundInput) {
    this._boundInput.value = selectedDates.join(',')
  }

  if (this._displayElement) {
    this._displayElement.textContent = formattedDate
  }
}

edits.after:
protected _syncSelectedDates(selectedDates: string[]): void {
  if (selectedDates.length === 0) {
    if (this._displayElement) {
      this._displayElement.textContent = ''
    }
    if (this._isInput) {
      this._element.value = ''
    }
    if (this._boundInput) {
      this._boundInput.value = ''
    }
    return
  }

  const formattedDate = this._formatDateForInput(selectedDates)
  if (this._displayElement) {
    this._displayElement.textContent = formattedDate
  }

  if (this._isInput) {
    this._element.value = selectedDates.join(',')
  }

  if (this._boundInput) {
    this._boundInput.value = selectedDates.join(',')
  }
}
